{"id":"PIR-1351","opened":"2026-08-29T14:00:00.000Z","resolved":"2026-08-29T14:35:00.000Z","sev":"SEV3","title":"Slow portfolio pages during database maintenance","services":["portfolio-service","database"],"symptoms":"Portfolio p95 latency rose to 900 ms for 20 minutes.","root_cause":"A manual VACUUM on the holdings table ran during business hours.","resolution":"Maintenance moved to the night window; added a guard to the runbook.","tags":["database","latency","maintenance"],"match_score":2}
